"""Instrument actual emitted API B2 native code and its C boundary glue."""
from pathlib import Path
import hashlib,json,os,re,shlex,subprocess,sys,tempfile
ROOT=Path(__file__).resolve().parents[2]
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def main(compiler_arg,output_arg):
	compiler=Path(compiler_arg).resolve();output=Path(output_arg).resolve();assert not output.is_relative_to(ROOT);output.mkdir(parents=True,exist_ok=True);work=Path(tempfile.mkdtemp(prefix='byte-api-b2-sanitizers-',dir=output));here=Path(__file__).resolve().parent;runtime=ROOT/'lib/runtime/interop';inputs=[here/('api-b2'+suffix) for suffix in ['-leaf.astra','-component.astra','-protocol.astra','-native.astra']];files=[Path(__file__).resolve(),*inputs,here/'api-b2-support.c',here/'api-b2-client.c',here/'api-b2-native-client.c',here/'api-b2-gobject-client.c',runtime/'foreign-14.c'];receipt=dict(scope='actual emitted Astra native code and C/GObject glue instrumented with ASan; C also UBSan; installed GLib/GObject remains uninstrumented; no method-state race-freedom claim',compiler_sha256=sha(compiler),sources={str(p.relative_to(ROOT)):sha(p) for p in files},checks=[])
	def run(command,contains=''):
		assert sha(compiler)==receipt['compiler_sha256'];p=subprocess.run(list(map(str,command)),text=True,capture_output=True,cwd=work,timeout=120,env=dict(os.environ,G_DEBUG='fatal-warnings',ASAN_OPTIONS='detect_leaks=1:halt_on_error=1',UBSAN_OPTIONS='halt_on_error=1:print_stacktrace=1',PYTHONDONTWRITEBYTECODE='1'));receipt['checks'].append(dict(command=list(map(str,command)),exit=p.returncode,stdout=p.stdout,stderr=p.stderr));(work/'checks.json').write_text(json.dumps(receipt,indent=2)+'\n');assert p.returncode==0 and contains in p.stdout+p.stderr and 'ERROR: AddressSanitizer' not in p.stderr and 'runtime error:' not in p.stderr,receipt['checks'][-1];return p.stdout
	selected=[compiler,'--foreign-personalities=c,gobject'];target=dict(line.split('=',1) for line in run([compiler,'--target-info']).splitlines() if '=' in line);receipt['target']=target;text=run([*selected,'--dump-llvm',*inputs]);assert not re.search(r'^target (?:datalayout|triple)',text,re.M);text='target datalayout = '+json.dumps(target['data-layout'])+'\ntarget triple = '+json.dumps(target['target'])+'\n'+text;text=re.sub(r'^(define .*?)\s*\{\s*$',r'\1 sanitize_address {',text,flags=re.M);raw=work/'native.ll';raw.write_text(text);instrumented=work/'native-asan.ll';run(['opt','-passes=default<O1>,asan','-S',raw,'-o',instrumented]);assert '__asan_report_' in instrumented.read_text();obj=work/'native-asan.o';run(['llc','-O1','-filetype=obj','-relocation-model=pic',instrumented,'-o',obj]);adapter=work/'adapter.c';adapter.write_text(run([*selected,'--emit-gobject-source',*inputs]));flags=shlex.split(run(['pkg-config','--cflags','--libs','gobject-2.0']))
	for name,message in [('client','PASS frozen API B2 independent record query'),('native-client','PASS frozen API B2 native query algorithms'),('gobject-client','PASS frozen API B2 GObject record inputs')]:
		client=work/name;run(['clang','-std=gnu11','-O1','-g','-Wall','-Wextra','-Werror','-fsanitize=address,undefined','-fno-omit-frame-pointer','-no-pie','-pthread',here/('api-b2-'+name+'.c'),here/'api-b2-support.c',runtime/'foreign-14.c',adapter,obj,*flags,'-o',client]);run([client],contains=message)
	receipt['status']='API_B2_EMITTED_NATIVE_ASAN_C_UBSAN_PASS';receipt['products']={p.name:sha(p) for p in [raw,instrumented,obj,adapter]};(work/'checks.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(dict(status=receipt['status'],commands=len(receipt['checks']),receipt=str(work/'checks.json'))))
if __name__=='__main__':main(*sys.argv[1:])
